// MurmurHash2 implementation for LevelDB
const uint32_t m = 0x5bd1e995;
const int r = 24;

uint32_t h = seed ^ static_cast<uint32_t>(n);
const unsigned char* d = reinterpret_cast<const unsigned char*>(data);

while (n >= 4) {
    uint32_t k;
    std::memcpy(&k, d, sizeof(uint32_t));
    k *= m;
    k ^= k >> r;
    k *= m;

    h *= m;
    h ^= k;

    d += 4;
    n -= 4;
}

switch (n) {
    case 3:
        h ^= d[2] << 16;
        FALLTHROUGH_INTENDED;
    case 2:
        h ^= d[1] << 8;
        FALLTHROUGH_INTENDED;
    case 1:
        h ^= d[0];
        h *= m;
}

h ^= h >> 13;
h *= m;
h ^= h >> 15;

return h;

